css:
.cn-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #04060f; }
.cn-stage canvas { touch-action: none; cursor: grab; }
.cn-tools { position: absolute; right: 14px; top: 12px; display: flex; gap: 8px; z-index: 3; }
.cn-tools .btn { font-size: 19px !important; padding: 8px 14px !important; }
.cn-lab { font-size: 18px; padding: 2px 10px; }
.cn-small { font-size: 15px; opacity: .85; }
.cn-g { background: #ff4d4d; color: #fff; border-color: #fff; font-size: 17px; }
.cn-v { background: #4dd2ff; color: #062033; border-color: #fff; font-size: 17px; }
.cn-shot { font: 800 16px var(--f-body); padding: 1px 8px; background: var(--c); color: #111; border-color: #111; }
.cn-handle { position: absolute; left: 0; top: 0; z-index: 4; display: grid; justify-items: center; gap: 4px; padding: 8px 8px 6px; border-radius: 14px; background: rgba(10,14,32,.8); border: 2px solid #8fa3d0; color: #e8eefc; touch-action: none; cursor: ns-resize; user-select: none; }
.cn-handle:focus-visible { outline: 4px solid var(--hl); }
.cn-handle.drag { border-color: #ffd84d; }
.cn-h-cap { font: 700 14px var(--f-body); }
.cn-h-unit { font: 600 13px var(--f-body); opacity: .8; }
.cn-track { position: relative; width: 14px; height: 170px; margin: 12px 0; border-radius: 7px; background: linear-gradient(#ff6b8a, #ffd84d 45%, #6fc3ff); }
.cn-knob { position: absolute; left: 50%; bottom: 0; transform: translate(-50%, 50%); min-width: 58px; text-align: center; font: 800 20px/1 var(--f-body); color: #111; background: #fff; border: 3px solid #111; border-radius: 10px; padding: 6px 6px; box-shadow: 0 2px 8px rgba(0,0,0,.4); }
.cn-gauge { position: absolute; left: 14px; bottom: 14px; display: grid; gap: 2px; min-width: 170px; padding: 10px 14px; border-radius: 12px; background: rgba(10,14,32,.82); border: 2px solid #5a6a90; color: #fbfcf9; font: 600 17px/1.35 var(--f-body); pointer-events: none; }
.cn-gauge b { font: 800 26px/1.2 var(--f-body); color: #ffd84d; }
.cn-k { font-weight: 800; }
.cn-k.orbit { color: #7ee081; } .cn-k.ellipse { color: #e48cff; } .cn-k.fall { color: #ffb347; }
.cn-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; }
.cn-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-size: 19px; }
.cn-list li { display: grid; grid-template-columns: 18px 110px 1fr; align-items: center; gap: 8px; padding: 2px 8px; border-bottom: 1.5px solid var(--rule); }
.cn-list i { width: 16px; height: 16px; border-radius: 50%; background: var(--c); border: 2px solid var(--ink); }

